// Bir butona basilinca LED yak (sozde-register ornegi)
#define LED_PIN  13
#define BTN_PIN   2

void setup() {
    pinMode(LED_PIN, OUTPUT);
    pinMode(BTN_PIN, INPUT_PULLUP);
}

void loop() {
    int basili = (digitalRead(BTN_PIN) == LOW);
    digitalWrite(LED_PIN, basili ? HIGH : LOW);
}

#include <Adafruit_PN532.h>
Adafruit_PN532 nfc(SDA, SCL);

void setup(){ Serial.begin(115200); nfc.begin(); nfc.SAMConfig(); }

void loop(){
  uint8_t uid[7]; uint8_t len;
  if (nfc.readPassiveTargetID(PN532_MIFARE_ISO14443A, uid, &len)) {
    Serial.print("UID: ");
    for (uint8_t i=0;i<len;i++){ Serial.print(uid[i],HEX); Serial.print(' '); }
    Serial.println();
  }
}
